141	// resolveUnionOfObjects takes an object expression and its corresponding schema union type,
142	// then tries to find out which type from the union is the one that matches the object expression.
143	// We do this based on the discriminator field in the object expression.
144	func resolveUnionOfObjects(objectExpr *model.ObjectConsExpression, union *schema.UnionType) schema.Type {
145		var discriminatorValue string
146		for _, item := range objectExpr.Items {
147			if key, ok := item.Key.(*model.LiteralValueExpression); ok {
148				if key.Value.AsString() == union.Discriminator {
149					if value, ok := item.Value.(*model.LiteralValueExpression); ok {
150						discriminatorValue = value.Value.AsString()
151						break
152					}
153	
154					if value, ok := item.Value.(*model.TemplateExpression); ok && len(value.Parts) == 1 {
155						if literalValue, ok := value.Parts[0].(*model.LiteralValueExpression); ok {
156							discriminatorValue = literalValue.Value.AsString()
157							break
158						}
159					}
160				}
161			}
162		}
163	
164		if discriminatorValue == "" {
165			return union
166		}
