250		}
251	
252		var src Type
253		switch t := t.(type) {
254		case *OutputType:
255			return t
256		case *PromiseType:
257			src = NewPromiseType(inputTypeImpl(t.ElementType, seen))
258		case *MapType:
259			src = NewMapType(inputTypeImpl(t.ElementType, seen))
260		case *ListType:
261			src = NewListType(inputTypeImpl(t.ElementType, seen))
262		case *UnionType:
263			elementTypes := make([]Type, len(t.ElementTypes))
264			for i, t := range t.ElementTypes {
265				elementTypes[i] = inputTypeImpl(t, seen)
266			}
267			src = NewUnionTypeAnnotated(elementTypes, t.Annotations...)
268		case *ObjectType:
269			if already, ok := seen[t]; ok {
270				return already
271			}
272	
273			properties := map[string]Type{}
274			src = NewObjectType(properties, t.Annotations...)
275			seen[t] = src
276			for k, t := range t.Properties {
277				properties[k] = inputTypeImpl(t, seen)
278			}
279		default:
280			src = t
281		}
282	
283		return NewUnionType(src, NewOutputType(src))
