44	// NewUnionTypeAnnotated creates a new union type with the given element types and annotations.
45	// NewUnionTypeAnnotated enforces 3 properties on the returned type:
46	// 1. Any element types that are union types are replaced with their element types.
47	// 2. Any duplicate types are removed.
48	// 3. Unions have have more then 1 type. If only a single type is left after (1) and (2),
49	// it is returned as is.
50	func NewUnionTypeAnnotated(types []Type, annotations ...any) Type {
51		var elementTypes []Type
52		for _, t := range types {
53			if union, isUnion := t.(*UnionType); isUnion {
54				elementTypes = append(elementTypes, union.ElementTypes...)
55			} else {
56				elementTypes = append(elementTypes, t)
57			}
58		}
59	
60		// Remove duplicate types
61		// We first sort the types so duplicates will be adjacent
62		sort.Slice(elementTypes, func(i, j int) bool {
63			return elementTypes[i].String() < elementTypes[j].String()
64		})
65		// We then filter out adjacent duplicates
66		dst := 0
67		for src := 0; src < len(elementTypes); {
68			for src < len(elementTypes) && elementTypes[src].Equals(elementTypes[dst]) {
69				src++
70			}
71			dst++
72	
73			if src < len(elementTypes) {
74				elementTypes[dst] = elementTypes[src]
75			}
76		}
77		elementTypes = elementTypes[:dst]
78	
79		// If the union turns out to be the union of a single type, just return the underlying
80		// type.
81		if len(elementTypes) == 1 {
82			return elementTypes[0]
83		}
84	
85		return &UnionType{ElementTypes: elementTypes, Annotations: annotations, cache: &gsync.Map[Type, cacheEntry]{}}
86	}
