// lists of hook references. It returns an expression that, when evaluated, produces an object where each key is a
// lifecycle event name and each value is a tuple of hook name strings.
func bindResourceHooks(expr model.Expression) (model.Expression, hcl.Diagnostics) {
	var diagnostics hcl.Diagnostics

	hooksError := func() *hcl.Diagnostic {
		return errorf(expr.SyntaxNode().Range(),
			"hooks option must be an object mapping hook names to lists of hook references")
	}

	objectExpr, ok := expr.(*model.ObjectConsExpression)
	if !ok {
		diagnostics = append(diagnostics, hooksError())
		return expr, diagnostics
	}

	items := make([]model.ObjectConsItem, 0, len(objectExpr.Items))
	for _, item := range objectExpr.Items {
		key, isLiteral := literalExprValue(item.Key)
		if !isLiteral || !key.Type().Equals(cty.String) {
			diagnostics = append(diagnostics, hooksError())
			continue
